"""Generate dependency-free static pages. Run from any directory with Python 3.12+."""
from pathlib import Path
from html import escape
ROOT = Path(__file__).resolve().parents[1]
NAV = [('Home','/'),('Research','/research/'),('Experience','/experience/'),('About','/about/'),('Contact','/contact/')]
def link(url, text, cls='text-link'):
    return f'<a class="{cls}" href="{url}">{text} <span aria-hidden="true"><svg class="arrow" aria-hidden="true" width="13" height="13" viewBox="0 0 16 16"><path d="M3 13 13 3M3 3h10v10" fill="none" stroke="currentColor" stroke-width="1.4"/></svg></span></a>'
def intro(kicker,title,desc):
    return f'<header class="page-intro"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{desc}</p></header>'
def row(num,title,desc,meta=''):
    return f'<article class="research-row"><span class="index">{num}</span><div><p class="eyebrow">{meta}</p><h3>{title}</h3><p>{desc}</p></div></article>'
thesis_title='Hallucination-Aligned Visual Negative Construction for Multimodal DPO'
feature=f'''<article class="feature"><div><p class="eyebrow">Featured research · Honours thesis, 2026</p><h2>Teaching models to see<br>what is really there.</h2><p>{thesis_title}. Constructing visual negatives aligned with a model’s own hallucinations for cross-modal preference training.</p>{link('/research/thesis/','Explore the research','button')}</div><div class="feature-art" aria-label="Conceptual process: observation, verification, alignment"><span class="art-label">FROM PERCEPTION TO PREFERENCE</span><div class="orbit"><span>Observe</span><span>Verify</span><span>Align</span></div><p>Better evidence.<br><em>More grounded reasoning.</em></p></div></article>'''
pages={
'/':('Xin Yu — Multimodal reasoning & trustworthy AI','Academic portfolio of Xin Yu, an M.S. Artificial Intelligence student at Columbia University.',f'''<section class="hero"><div><p class="eyebrow"><span class="status-dot"></span> Xin Yu · Columbia University</p><h1>Reasoning beyond<br>what models <em>see.</em></h1><p class="hero-description">I study how multimodal models understand the visual world—and how to make their reasoning more grounded, reliable, and trustworthy.</p><p class="affiliation">M.S. Artificial Intelligence <span> / </span> Columbia University</p><div class="actions">{link('/research/','Discover my research','button')}{link('/about/','A little about me')}</div></div><aside class="hero-note"><span class="note-number">01 / RESEARCH FOCUS</span><p>Seeing is a start.<br><em>Understanding is the goal.</em></p><div class="fine-rule"></div><span>Multimodal reasoning<br>Vision-language models<br>Trustworthy AI</span></aside></section><section class="section">{feature}</section><section class="section"><div class="section-heading"><div><p class="eyebrow">An evolving research agenda</p><h2>Grounded in evidence.</h2></div>{link('/research/','All research')}</div><div class="three-grid"><article><span class="index">01</span><h3>Multimodal reasoning</h3><p>Understanding relationships across images, language, and visual evidence.</p></article><article><span class="index">02</span><h3>Preference optimization</h3><p>Exploring how training signals can align model responses with what is visible.</p></article><article><span class="index">03</span><h3>Verified synthetic data</h3><p>Building more useful training data through generation, filtering, and verification.</p></article></div></section><section class="closing"><p class="eyebrow">Research is a conversation</p><h2>Let’s ask better questions.</h2><p>Interested in multimodal learning, reliable AI, and research collaborations.</p>{link('/contact/','Get in touch')}</section>'''),
'/research/':('Research & publications — Xin Yu','Research in multimodal reasoning, visual hallucination, preference optimization, and verified synthetic data.',intro('Research & publications','Making visual intelligence<br><em>more reliable.</em>','My interests span multimodal reasoning, vision-language models, visual hallucination, preference optimization, synthetic data, and trustworthy AI.')+'''<section class="section"><div class="section-heading"><h2>Manuscript under review</h2><span class="small">01 / SELECTED WORK</span></div><article class="publication"><span class="badge">Under review · ICLR 2027 submission</span><h3>ReSynth: Verified Synthetic Data for Multi-Image Understanding</h3><p>A relation-based generation and visual-verification pipeline spanning five multi-image reasoning abilities. A 13K-example synthetic corpus was used to train Qwen2.5-VL-7B with GRPO; the reported +4.25-point average gain covers BLINK, MUIRBench, and VLM2-Bench. The +9.75-point counting gain is attributed to visual verification.</p><div class="metrics"><div><strong>13K</strong><span>Synthetic examples</span></div><div><strong>+4.25</strong><span>Average accuracy points</span></div><div><strong>+9.75</strong><span>Counting accuracy points</span></div></div><p class="small">Submission under review; not an accepted publication. Paper and author list pending.</p></article></section>'''+feature+'''<section class="section"><p class="eyebrow">Further investigations</p><h2>Selected research</h2>'''+row('01','Mitigating Visual Hallucination in VQA for MLLMs','Constructed positive/negative pairs by masking target regions and used caption-based supervision to distinguish visible evidence. Filtered 265K examples to 163K without accuracy loss, as reported in the CV.','Visual grounding')+row('02','Data Selection for GRPO-based MLLM Training','Developed advantage-based sample filtering and a vectorized Parquet processing pipeline. The CV reports roughly half of examples as ineffective and a high-value subset of approximately 5%.','Training data')+row('03','Curriculum Learning Strategies for MLLM Training','Evaluated 20 SFT checkpoints and built a 72K-example curriculum ranked by Pass@5 difficulty. Explored Naive GRPO and CoT Rollout GRPO with hint fading; early experiments indicated faster convergence than the baseline.','Learning strategies')+row('04','MacroNet: A Composable Neural Network Programming Framework',f'Contribution: PyTorch implementation, MLP/LeNet model experiments, reusable layer composition, and technical documentation with Prof. Min Li’s group (April 2025–present). {link("https://github.com/sumowi/MacroNet","View the framework")}','Research software')+row('05','Multimodal verification research','Research Assistant &amp; Project Lead with Prof. Lei Wang’s group / Hunan Jiace Test (June 2024–March 2025). Led a training-free, four-stage verification framework for software acceptance reports, using MiniCPM-V for evidence summaries and Qwen2-7B for consistency reasoning.','Verification')+'</section>'),
'/research/thesis/':('Visual negatives for multimodal DPO — Xin Yu','Honours thesis on hallucination-aligned visual negative construction, methodology, reported results, and limitations.',intro('Undergraduate Honours Thesis · 2026',thesis_title,'Can the mistakes a model makes become a better training signal? This thesis explores visual negatives tailored to a model’s own hallucinations.')+'''<div class="thesis-meta"><span>Xin Yu</span><span>DI40001 DIICSU Honours Project · Supervisor: Yang Gao</span><span>Multimodal preference optimization</span></div><section class="section prose"><p class="eyebrow">The central idea</p><h2>Turn hallucinations into<br>targeted visual contrasts.</h2><p>Generic visual perturbations may not reflect the semantic mistakes made by a vision-language model. This project uses model rollouts and semantic difference extraction to guide negative image synthesis, then filters and verifies the resulting preference pairs before cross-modal DPO training.</p></section><section class="pipeline-section"><p class="eyebrow">Methodology</p><h2>From self-rollout to alignment.</h2><ol class="pipeline">'''+''.join(f'<li><span class="index">0{i}</span><h3>{t}</h3><p>{d}</p></li>' for i,(t,d) in enumerate([('Self-rollout','Qwen2.5-VL-3B-Instruct generates responses.'),('Judge & extract','Qwen3-8B judges responses and extracts semantic differences.'),('Synthesize','Qwen-Image constructs visual negatives.'),('Filter & verify','Filter and verify candidate training pairs.'),('Align','Train with cross-modal DPO.')],1))+'''</ol><p class="small">Pipeline summarized from the thesis, Sections 3–4. The contribution focuses on negative-data construction rather than a new DPO objective.</p></section><section class="section"><div class="two-grid"><div><p class="eyebrow">Key contributions</p><h2>Alignment begins<br>with the right contrast.</h2></div><ol class="contributions"><li><strong>Model-informed negatives.</strong> Use self-rollout errors to inform visual negative construction.</li><li><strong>Semantic guidance.</strong> Connect judging and difference extraction to image synthesis.</li><li><strong>Verified preference pairs.</strong> Filter candidate pairs before preference optimization.</li></ol></div><div class="metrics"><div><strong>15,732</strong><span>Source samples</span></div><div><strong>≈7.5K</strong><span>Filtered training pairs</span></div><div><strong>8,456</strong><span>Pairs after judge scoring</span></div></div><p class="small">Source datasets: RLAIF-V and RLHF-V. The thesis reports approximately 71% fully sampled pairs and 29% reference-answer fallback pairs (Table 3).</p></section><section class="section"><p class="eyebrow">Reported evaluation</p><h2>More grounded responses.</h2><div class="table-wrap"><table><caption>Reported in the thesis, Table 5 · Qwen2.5-VL-3B-Instruct</caption><thead><tr><th scope="col">Metric</th><th scope="col">Base model</th><th scope="col">DPO + cross-modal</th></tr></thead><tbody><tr><th scope="row">MMHal-Bench score ↑</th><td>3.82</td><td>3.99</td></tr><tr><th scope="row">Hallucination rate ↓</th><td>37.6%</td><td>33.3%</td></tr></tbody></table></div><p>Reported comparison with random-crop mDPO: <strong>+0.29 MMHal</strong>. The crop baseline scored 3.70; text-only DPO scored 3.94. The 3.99 result therefore represents +0.29 over crop-based mDPO and +0.05 over text-only DPO (Tables 5–6).</p></section><section class="section two-grid"><div><p class="eyebrow">Limitations & context</p><h2>Promising results.<br>Open questions.</h2></div><div><p>The thesis reports one epoch of full-parameter Qwen2.5-VL-3B-Instruct training on 8 × H100 GPUs, using DeepSpeed ZeRO-2, an effective batch size of 64, a learning rate of 5 × 10⁻⁷, and DPO β = 0.1 (Table 2). MMHal-Bench responses were scored with Qwen3-8B (Section 4.11), so these figures should be read within this evaluation setup rather than assumed directly comparable with other judge protocols.</p><p>The improvement is benchmark-dependent: Object HalBench CHAIRs increased from 19.7% to 24.3% (lower is better), while recall increased from 57.9% to 64.8%. The method does not improve every hallucination metric. Generation and judge errors can propagate; dataset size and token weighting were not fully ablated, and generalization beyond the evaluated model and visually depictable errors remains unestablished.</p><p class="editorial-note">Distinction reported by the author: “Outstanding Undergraduate Thesis” (Top 5%). Exact official award wording remains unconfirmed and is not asserted here as a verified award.</p><p class="small">The complete thesis PDF is intentionally not published because it contains personal acknowledgments. A public, redacted version is pending author review. No code release is claimed. The original thesis and CV were reviewed privately for this summary; neither original PDF is hosted here.</p></div></section>'''),
'/experience/':('Experience & projects — Xin Yu','Selected internships, research software, and team projects by Xin Yu.',intro('Experience & projects','Ideas into<br><em>working systems.</em>','Selected experience across AI development, model experiments, and collaborative software projects.')+'<section class="section"><h2>Experience</h2>'+row('01','BROAD Group','AI Developer Intern · January–March 2025. Curated 50K user texts into 3K dialogues and fine-tuned Qwen2.5-7B with LlamaFactory. Built an AI-VTuber streaming system integrating live chat, text-to-speech, containerized deployment, and VTuber Studio.','AI development')+row('02','Hunan Jiace Test','Technical Development Intern · September 2024–March 2025. Developed 15 REST APIs with reported average latency below 0.5 seconds, alongside multimodal model development.','Industry experience')+'</section><section class="section"><h2>Projects</h2>'+row('01','MiniB platform','Team Lead · September–October 2025. Built the backend and database for a Vue3 school–enterprise collaboration platform supporting multi-role access, project matching, and resource sharing. Coordinated delivery of a client-simulated enterprise project.','Team project')+row('02','DIICSU classroom management system','Co-Team Lead · March 2025. Co-led an eight-member Agile team delivering a classroom management system in four weeks. Designed a MySQL schema and approximately 40 Flask/JavaScript REST APIs; deployed on Azure with SSL. Course result: 97/100, as reported in the CV.','Team project')+row('03','MacroNet','Implementation and model experiments for a composable neural network programming framework. '+link('https://github.com/sumowi/MacroNet','Explore on GitHub'),'Research software')+'</section>'),
'/about/':('About & education — Xin Yu','Xin Yu studies Artificial Intelligence at Columbia University, following Computer Science at Central South University.',intro('About Xin Yu','Curiosity, grounded<br><em>in the visual world.</em>','I am an M.S. student in Artificial Intelligence at Columbia University, interested in how multimodal models reason—and how we can trust what they say.')+'''<section class="section two-grid"><div><p class="eyebrow">Perspective</p><h2>From seeing<br>to understanding.</h2></div><div class="prose"><p>My research interests connect visual understanding with reliable learning: multimodal reasoning, vision-language models, visual hallucination, preference optimization, synthetic data, and trustworthy AI.</p><p>Through research and implementation, I explore how the quality of evidence and training data shapes model behavior.</p></div></section><section class="section"><p class="eyebrow">Education</p><h2>A foundation for exploration.</h2>'''+row('01','Columbia University','M.S. Artificial Intelligence','September 2026 – December 2027')+row('02','Central South University','B.S. Computer Science and Technology · First-Class Honours. Joint undergraduate program with the University of Dundee; weighted average 90.58/100.','September 2022 – June 2026')+'</section><section class="section two-grid"><div><p class="eyebrow">Research &amp; engineering</p><h2>Tools for experimentation.</h2></div><div><h3>Model training</h3><p>PyTorch, Hugging Face Transformers, LlamaFactory; SFT, DPO, and GRPO.</p><h3>Engineering</h3><p>Python, C++, SQL, Java, and R; Linux, Git, Docker, AWS, Azure, Flask, and MySQL.</p><h3>Research experience</h3><p>Research Assistant with Prof. Jinpeng Wang’s group and Prof. Min Li’s group, April 2025–present, as listed in the CV.</p></div></section>'),
'/contact/':('Contact — Xin Yu','Connect with Xin Yu about multimodal learning, trustworthy AI, and research opportunities.',intro('Contact','Good research starts<br>with a <em>conversation.</em>','I welcome conversations about multimodal reasoning, trustworthy AI, research collaborations, and ML engineering opportunities.')+f'''<section class="contact-panel"><p class="eyebrow">Find me online</p><h2>Xin Yu</h2><p>M.S. Artificial Intelligence<br>Columbia University</p>{link('https://github.com/yuxin0923','GitHub · yuxin0923','button')}<p class="small">Email: <a href="mailto:xy2765@columbia.edu">xy2765@columbia.edu</a>. A downloadable public CV will follow after a privacy review.</p></section>''')}
for path,(title,description,body) in pages.items():
    nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if (path==url or url=='/research/' and path.startswith('/research/')) else '')+f'>{label}</a>' for label,url in NAV)
    html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(description)}"><meta name="color-scheme" content="light dark"><link rel="canonical" href="https://yuxin0923.github.io{path}"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(description)}"><meta property="og:type" content="website"><meta property="og:url" content="https://yuxin0923.github.io{path}"><meta property="og:image" content="https://yuxin0923.github.io/assets/social.png"><meta name="twitter:card" content="summary"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><script src="/assets/theme.js"></script><link rel="stylesheet" href="/assets/style.css"><script src="/assets/main.js" defer></script></head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="/" aria-label="Xin Yu home">Xin Yu<span>.</span></a><div class="nav-controls"><button class="theme-toggle" type="button" aria-label="Switch color theme" hidden>◐</button><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="navigation" hidden>Menu <span aria-hidden="true">☰</span></button></div><nav id="navigation" aria-label="Main navigation">{nav}</nav></header><main id="main">{body}</main><footer><a class="brand" href="/">Xin Yu<span>.</span></a><p>Multimodal reasoning. Grounded intelligence.</p><a href="/contact/">Connect <svg class="arrow" aria-hidden="true" width="13" height="13" viewBox="0 0 16 16"><path d="M3 13 13 3M3 3h10v10" fill="none" stroke="currentColor" stroke-width="1.4"/></svg></a><span class="copyright">© 2026 Xin Yu</span></footer></body></html>'''
    dest=ROOT / path.strip('/') / 'index.html'; dest.parent.mkdir(parents=True,exist_ok=True); dest.write_text(html)
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>https://yuxin0923.github.io{p}</loc></url>' for p in pages)+'</urlset>')
print(f'Generated {len(pages)} pages and sitemap.')
